// Tadpoles — Animation, route: jsx
// Source: tadpoles
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';

// The swim runs in a fixed virtual box and the viewBox scales it, so the simulation
// is width-independent: resizing the container never perturbs or restarts the swarm.
const BOX = { width: 1000, height: 600 };
const COUNT = 26;
const SEGMENTS = 14;
const SPEED = 2;
// Ticks run before the first paint, so even a server-rendered frame shows extended
// tails rather than the field of coincident points a cold start would draw.
const WARMUP = 220;

type Tadpole = {
  id: number;
  vx: number;
  vy: number;
  px: number[];
  py: number[];
  phase: number;
};

type Pose = { id: number; x: number; y: number; angle: number; body: string; tail: string };

// mulberry32, fixed seed: the same swarm every load, and no Math.random anywhere.
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createSwarm(): Tadpole[] {
  const random = seededRandom(0x7ad9013);
  return Array.from({ length: COUNT }, (_, id) => {
    const x = random() * BOX.width;
    const y = random() * BOX.height;
    // Polar rather than two independent components: guarantees a nonzero speed, which
    // the spine math divides by on every segment.
    const heading = random() * 2 * Math.PI;
    const speed = (0.5 + 0.5 * random()) * SPEED;
    return {
      id,
      vx: Math.cos(heading) * speed,
      vy: Math.sin(heading) * speed,
      px: new Array<number>(SEGMENTS).fill(x),
      py: new Array<number>(SEGMENTS).fill(y),
      phase: 0
    };
  });
}

/** Advance one frame: move each head, then drag its spine behind it with a sine undulation. */
function step(swarm: Tadpole[]): void {
  for (const t of swarm) {
    let dx = t.vx;
    let dy = t.vy;
    let x = (t.px[0] += dx);
    let y = (t.py[0] += dy);
    let speed = Math.max(Math.hypot(dx, dy), 1e-3);
    const advance = speed * 10;
    const spacing = -5 - speed / 3;

    if (x < 0 || x > BOX.width) t.vx *= -1;
    if (y < 0 || y > BOX.height) t.vy *= -1;

    for (let j = 1; j < SEGMENTS; ++j) {
      const nextDx = x - t.px[j];
      const nextDy = y - t.py[j];
      // Lateral offset perpendicular to travel, phase-shifted down the spine. This is
      // the whole trick: it turns a trailing chain into a swimming tail.
      t.phase += advance;
      const wave = Math.sin((t.phase + j * 3) / 300) / speed;
      t.px[j] = (x += (dx / speed) * spacing) - dy * wave;
      t.py[j] = (y += (dy / speed) * spacing) + dx * wave;
      dx = nextDx;
      dy = nextDy;
      speed = Math.max(Math.hypot(dx, dy), 1e-3);
    }
  }
}

function toPoses(swarm: Tadpole[], spine: d3.Line<[number, number]>): Pose[] {
  return swarm.map((t) => {
    const points = t.px.map((x, i) => [x, t.py[i]] as [number, number]);
    return {
      id: t.id,
      x: t.px[0],
      y: t.py[0],
      angle: (Math.atan2(t.vy, t.vx) * 180) / Math.PI,
      body: spine(points.slice(0, 3)) ?? '',
      tail: spine(points) ?? ''
    };
  });
}

export default function Tadpoles({ width }: { width: number }) {
  const height = Math.round(width * (BOX.height / BOX.width));

  const spine = useMemo(
    () =>
      d3
        .line<[number, number]>()
        .curve(d3.curveCatmullRom)
        .x((p) => p[0])
        .y((p) => p[1]),
    []
  );

  const settled = useMemo(() => {
    const swarm = createSwarm();
    for (let i = 0; i < WARMUP; ++i) step(swarm);
    return swarm;
  }, []);

  const [poses, setPoses] = useState<Pose[]>(() => toPoses(settled, spine));

  useEffect(() => {
    let frame = requestAnimationFrame(function tick() {
      step(settled);
      setPoses(toPoses(settled, spine));
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  }, [settled, spine]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${BOX.width} ${BOX.height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`${COUNT} tadpoles swimming freely, each dragging an undulating tail behind it and bouncing off the edges of the frame`}
    >
      <g
        fill="var(--accent)"
        stroke="var(--accent)"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {poses.map((pose) => (
          <g key={pose.id}>
            <path d={pose.tail} fill="none" strokeWidth={2} />
            <path d={pose.body} fill="none" strokeWidth={4} />
            <ellipse
              rx={6.5}
              ry={4}
              stroke="none"
              transform={`translate(${pose.x.toFixed(2)},${pose.y.toFixed(2)}) rotate(${pose.angle.toFixed(2)})`}
            />
          </g>
        ))}
      </g>
    </svg>
  );
}
